SELECT CNTN_LOG_SN as cntnLogSn, USER_SN as userSn, USER_ID as userId, USER_NM as userNm, IP_ADDR as ipAddr, USER_AGT_NM as userAgtNm, RFRER_ADDR as rfrerAddr, SSN_ID as ssnId, DMND_URI_ADDR as dmndUriAddr, DMND_MTHD_CD as dmndMthdCd, RSPNS_STTS_CD as rspnsSttsCd, CNTN_TYPE_CD as cntnTypeCd, REG_DT as regDt FROM USER_ACCESS_LOG WHERE 1=1
AND USER_ID LIKE CONCAT('%', #{userId}, '%')
AND USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND IP_ADDR LIKE CONCAT('%', #{ipAddr}, '%')
AND CNTN_TYPE_CD = #{cntnTypeCd}
AND DATE(REG_DT) >= #{startDate}
AND DATE(REG_DT) <= #{endDate}
ORDER BY REG_DT DESC LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM USER_ACCESS_LOG
WHERE 1=1

	AND USER_ID LIKE CONCAT('%', #{userId}, '%')


	AND USER_NM LIKE CONCAT('%', #{userNm}, '%')


	AND IP_ADDR LIKE CONCAT('%', #{ipAddr}, '%')


	AND CNTN_TYPE_CD = #{cntnTypeCd}


	AND DATE(REG_DT) >= #{startDate}


	AND DATE(REG_DT) <= #{endDate}
